import { useState, useEffect, useMemo } from "react";
import { MapContainer, TileLayer, Popup, useMapEvents, GeoJSON, useMap, Tooltip } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';
import { useNavigate } from "react-router-dom";
import "../styles/AdminDashboard.css";

// Thành phần điều khiển Zoom và Center của bản đồ
function MapController({ zones, selectedDistrict, districts }) {
  const map = useMap();

  useEffect(() => {
    if (!zones || zones.length === 0) {
      if (selectedDistrict) {
        const dist = districts.find(d => d.id === selectedDistrict);
        if (dist && dist.center_lat) {
          map.flyTo([dist.center_lat, dist.center_lng], 13);
        }
      }
      return;
    }

    const bounds = [];
    zones.forEach(z => {
      if (z.center_lat && z.center_lng) bounds.push([z.center_lat, z.center_lng]);
      if (z.geometry && z.geometry.coordinates) {
        try {
          const coords = z.geometry.type === 'Polygon' ? z.geometry.coordinates[0] : z.geometry.coordinates[0][0];
          coords.forEach(coord => bounds.push([coord[1], coord[0]]));
        } catch(e) {}
      }
    });

    if (bounds.length > 0) {
      map.fitBounds(L.latLngBounds(bounds), { padding: [50, 50], maxZoom: 15 });
    }
  }, [zones, selectedDistrict, map, districts]);

  return null;
}

const API_BASE = "http://localhost:8000";

export default function AdminDashboard() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("zones");
  const [districts, setDistricts] = useState([]);
  const [allZones, setAllZones] = useState([]); // Lưu trữ tất cả zones từ DB
  const [territories, setTerritories] = useState([]);
  const [statistics, setStatistics] = useState({});
  
  const [selectedDistrict, setSelectedDistrict] = useState(null);
  const [showDistrictForm, setShowDistrictForm] = useState(false);
  const [showZoneForm, setShowZoneForm] = useState(false);
  
  const [newDistrict, setNewDistrict] = useState({ code: "", name: "", center_lat: 21.0285, center_lng: 105.8542, total_area: 0 });
  const [newZone, setNewZone] = useState({ code: "", name: "", center_lat: 0, center_lng: 0, customers: 0, orders: 0, revenue: 0 });
  
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  useEffect(() => {
    fetchDistricts();
    fetchAllZones(); // Lấy tất cả zones ngay khi load
    fetchStatistics();
  }, []);

  // Lấy danh sách District
  const fetchDistricts = async () => {
    try {
      const res = await fetch(`${API_BASE}/districts`);
      const data = await res.json();
      setDistricts(data);
    } catch (err) { setError("Không thể tải danh sách districts"); }
  };

  // Lấy TẤT CẢ Zones của TẤT CẢ Districts
  const fetchAllZones = async () => {
    try {
      const res = await fetch(`${API_BASE}/zones`);
      const data = await res.json();
      setAllZones(data);
    } catch (err) { console.error("Lỗi tải toàn bộ zones"); }
  };

  // Lấy Territories khi chọn District
  useEffect(() => {
    if (selectedDistrict) {
      fetchTerritories(selectedDistrict);
    }
  }, [selectedDistrict]);

  const fetchTerritories = async (districtId) => {
    try {
      const res = await fetch(`${API_BASE}/territories?district_id=${districtId}`);
      const data = await res.json();
      setTerritories(data);
    } catch (err) { console.error(err); }
  };

  const fetchStatistics = async () => {
    try {
      const res = await fetch(`${API_BASE}/admin/statistics`);
      const data = await res.json();
      setStatistics(data);
    } catch (err) { console.error(err); }
  };

  // Logic lọc Zone để hiển thị trên bản đồ
  const displayedZones = useMemo(() => {
    if (!selectedDistrict) return allZones; // Nếu chưa chọn district nào, hiện tất cả
    return allZones.filter(z => z.district_id === selectedDistrict); // Nếu chọn rồi, chỉ hiện của district đó
  }, [allZones, selectedDistrict]);

  // Hàm tạo màu sắc khác nhau cho từng Zone
  const getZoneColor = (id) => {
    return `hsl(${(id * 137.5) % 360}, 70%, 50%)`;
  };

  // Xử lý tạo District mới
  const handleAddDistrict = async () => {
    if (!newDistrict.code || !newDistrict.name) {
      setError("Vui lòng nhập mã và tên quận");
      return;
    }
    try {
      const res = await fetch(`${API_BASE}/districts`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newDistrict),
      });
      if (!res.ok) throw new Error("Mã quận đã tồn tại");
      setSuccess("Tạo quận mới thành công!");
      fetchDistricts();
      setShowDistrictForm(false);
      setNewDistrict({ code: "", name: "", center_lat: 21.0285, center_lng: 105.8542, total_area: 0 });
    } catch (err) { setError(err.message); }
  };

  const handleLogout = () => {
    localStorage.clear();
    navigate("/");
  };

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <div className="header-content">
          <h1>🏢 Quản lý Phân vùng Thương mại</h1>
          <button className="logout-btn" onClick={handleLogout}>Đăng xuất</button>
        </div>
      </header>

      <div className="dashboard-wrapper">
        <aside className="sidebar">
          <nav className="nav-menu">
            <button className={`nav-item ${activeTab === "zones" ? "active" : ""}`} onClick={() => setActiveTab("zones")}>📍 Quản lý Zones</button>
            <button className={`nav-item ${activeTab === "dashboard" ? "active" : ""}`} onClick={() => setActiveTab("dashboard")}>📊 Thống kê</button>
          </nav>
        </aside>

        <main className="main-content">
          {activeTab === "zones" && (
            <div className="content-section">
              <div className="section-header">
                <h2>📍 Bản đồ Phân vùng</h2>
                <div className="header-actions">
                  <button className="btn-primary" onClick={() => setShowDistrictForm(true)}>➕ Thêm Quận Mới</button>
                  <button className="btn-secondary" onClick={() => setSelectedDistrict(null)}>🌍 Xem Tất Cả Zones</button>
                </div>
              </div>

              {/* Form Thêm District */}
              {showDistrictForm && (
                <div className="form-container modal">
                  <h3>Tạo Quận/Huyện Mới</h3>
                  <div className="form-grid">
                    <input type="text" placeholder="Mã Quận (VD: CG)" value={newDistrict.code} onChange={e => setNewDistrict({...newDistrict, code: e.target.value})} />
                    <input type="text" placeholder="Tên Quận (VD: Cầu Giấy)" value={newDistrict.name} onChange={e => setNewDistrict({...newDistrict, name: e.target.value})} />
                    <input type="number" placeholder="Vĩ độ (Lat)" value={newDistrict.center_lat} onChange={e => setNewDistrict({...newDistrict, center_lat: parseFloat(e.target.value)})} />
                    <input type="number" placeholder="Kinh độ (Lng)" value={newDistrict.center_lng} onChange={e => setNewDistrict({...newDistrict, center_lng: parseFloat(e.target.value)})} />
                  </div>
                  <div className="form-actions">
                    <button className="btn-success" onClick={handleAddDistrict}>Lưu Quận</button>
                    <button className="btn-secondary" onClick={() => setShowDistrictForm(false)}>Hủy</button>
                  </div>
                </div>
              )}

              <div className="map-container" style={{ height: '600px', marginTop: '20px', border: '2px solid #ddd', borderRadius: '12px', overflow: 'hidden' }}>
                <MapContainer center={[21.0285, 105.8542]} zoom={12} style={{ height: '100%', width: '100%' }}>
                  <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
                  
                  <MapController zones={displayedZones} selectedDistrict={selectedDistrict} districts={districts} />

                  {displayedZones.map((z) => {
                    if (!z.geometry) return null;
                    const zoneColor = getZoneColor(z.id);

                    return (
                      <GeoJSON 
                        key={`${selectedDistrict ? 'dist' : 'all'}-${z.id}`}
                        data={z.geometry}
                        style={{
                          color: zoneColor,
                          fillColor: zoneColor,
                          fillOpacity: 0.4,
                          weight: 2
                        }}
                      >
                        {/* Hiển thị tên Zone cố định trên bản đồ */}
                        <Tooltip permanent direction="center" className="zone-label-tooltip">
                          {z.name}
                        </Tooltip>
                        
                        <Popup>
                          <div className="popup-info">
                            <h4>{z.name}</h4>
                            <p>Mã: {z.zone_code}</p>
                            <p>Khách hàng: {z.num_customers}</p>
                            <p>Doanh thu: {z.revenue.toLocaleString()} VND</p>
                          </div>
                        </Popup>
                      </GeoJSON>
                    );
                  })}
                </MapContainer>
              </div>

              <div className="district-selector" style={{ marginTop: '20px' }}>
                <h3>Danh sách Quận (Chọn để xem chi tiết)</h3>
                <div className="districts-grid">
                  {districts.map(d => (
                    <div 
                      key={d.id} 
                      className={`district-card ${selectedDistrict === d.id ? 'active' : ''}`}
                      onClick={() => setSelectedDistrict(d.id)}
                    >
                      <h4>{d.name}</h4>
                      <p>{d.code}</p>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {activeTab === "dashboard" && (
             <div className="content-section">
                <h2>📊 Thống kê hệ thống</h2>
                <div className="stats-grid">
                  <div className="stat-card"><h3>{statistics.total_zones}</h3><p>Tổng Zones</p></div>
                  <div className="stat-card"><h3>{statistics.total_sales}</h3><p>Nhân viên Sales</p></div>
                  <div className="stat-card"><h3>{statistics.total_revenue?.toLocaleString()}</h3><p>Doanh thu (VND)</p></div>
                </div>
             </div>
          )}
        </main>
      </div>
    </div>
  );
}
